mapper.update:
UPDATE train_gpu_lease
SET expires_at = #{newExpiresAt}, renewed_at = #{renewedAt},
    updated_at = #{renewedAt}
WHERE lease_id = #{leaseId} AND job_id = #{jobId}
  AND status = #{expectedStatus}

UPDATE train_gpu_lease
SET status = 'RELEASED', released_at = #{releasedAt},
    updated_at = #{releasedAt}
WHERE lease_id = #{leaseId} AND job_id = #{jobId}
  AND status = #{expectedStatus}

UPDATE train_gpu_lease
SET status = 'EXPIRED_QUARANTINED', updated_at = #{now}
WHERE status = 'ACTIVE' AND expires_at < #{now}
